// Matter Timeline visual baselines (#41): every viewport × theme project (360/768/1280, light and
// dark): the graph with the appeal chain, the timeline combined, lanes (1280 only), filtered, empty
// and error. The relative dates follow the server clock, so the Today marker label is masked.
// Baselines live in e2e/__screenshots__/matter-timeline and are only ever generated by the e2e
// workflow's `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md);
// without one the test is skipped. The graph with a collapsed W.M.P. group needs the 80-event
// synthetic matter and is covered by its Storybook story until that matter is seeded for e2e.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { MATTERS, MATTERS_WORKSPACE } from '../../fixtures/matters-data.ts';
import { expect, test } from '../../fixtures/index.ts';

import { openMatters } from './helpers.ts';

const matter = MATTERS.appeal;
const path = (query = '') =>
  query === '' ? `matters/${matter.id}/timeline` : `matters/${matter.id}/timeline?${query}`;

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  setUp: (page: Page, asUser: AsUser) => Promise<Locator | null>;
  /** Only at this width and up. */
  minWidth?: number;
}

const SHOTS: readonly Shot[] = [
  {
    name: 'timeline-combined.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: path() });
      await expect(page.locator('[data-event-id]').first()).toBeVisible();
      return null;
    },
  },
  {
    name: 'timeline-graph-appeal-chain.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: path() });
      const tree = page.getByRole('tree', { name: 'Proceedings of this matter' });
      await expect(tree).toBeVisible();
      return tree;
    },
    minWidth: 1280,
  },
  {
    name: 'timeline-lanes.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: path('mode=lanes') });
      await expect(page.getByRole('table', { name: /time axis/ })).toBeVisible();
      return null;
    },
    minWidth: 1280,
  },
  {
    name: 'timeline-filtered.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: path('k=listing&proposed=0') });
      await expect(page.locator('[data-event-id]').first()).toBeVisible();
      return null;
    },
  },
  {
    name: 'timeline-empty.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser, { path: path('__state=empty') });
      await expect(page.getByText('Nothing has happened on this matter yet.')).toBeVisible();
      return null;
    },
  },
  {
    name: 'timeline-error.png',
    setUp: async (page, asUser) => {
      await openMatters(page, asUser);
      await page.goto(`/w/${MATTERS_WORKSPACE}/${path('__state=error')}`);
      await expect(page.locator('main [data-pattern-state="error"]')).toBeVisible({
        timeout: 15_000,
      });
      return null;
    },
  },
];

test.describe('matter timeline visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        test.skip((page.viewportSize()?.width ?? 0) < (shot.minWidth ?? 0), 'wider viewports only');
        skipWithoutBaseline(testInfo, shot.name);
        const target = await shot.setUp(page, asUser);
        const options = {
          animations: 'disabled',
          caret: 'hide',
          mask: [page.locator('[data-today-marker]')],
        } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
